var a=[{title:`Posibili înlocuitori`,text:`Un rucsac închis, cu conținutul distribuit uniform, poate adăuga rezistență la o genuflexiune sau la o plimbare cu greutate. Sticlele cu apă merg ca gantere ușoare, iar o treaptă solidă poate înlocui o platformă joasă de exerciții. Aceste obiecte nu au dimensiuni sau marcaje de greutate standard, așa că sarcina și echilibrul se pot schimba fără avertisment.`},{title:`Mobila este un risc major`,text:`Un scaun de sufragerie poate aluneca sau se poate răsturna la scufundări pe scaun, urcări pe treaptă sau flotări înclinate, iar multe mese nu pot susține un ramat cu greutatea corpului tras de sub margine. Nu presupune niciodată că o masă obișnuită, un prosop, o clanță de ușă sau un raft îți poate ține greutatea corpului. Dacă o configurație depinde de o forță sau de o ancorare de care nu ești sigur, alege alt exercițiu.`},{title:`Verifică fiecare obiect`,text:`Asigură-te că suprafața nu alunecă, că recipientul nu curge și nu are mânere rupte și că bretelele rucsacului nu se rup. Distribuie greutatea ca să nu se balanseze brusc. Evită recipientele de sticlă, muchiile ascuțite de metal și stivele nesigure de cărți. Antrenează-te pe o podea liberă, departe de orice se poate sparge.`},{title:`Progresează încet`,text:`Începe cu o mișcare simplă și o sarcină mică. Repetările lente, care se pot repeta, sunt mai bune decât echilibrările dificile. Dacă nu poți cântări obiectul în mod sigur, notează configurația și o idee aproximativă despre rezistență, în loc de o cifră precisă. Păstrează fiecare creștere destul de mică încât să rămâi în control.`},{title:`Folosirea TrainUp`,text:`Un obiect din casă nu este o bancă, un rack, o bară de tracțiuni sau o stație de cabluri. În Profil, introdu un tip de bancă sau o bară de tracțiuni doar pentru echipamentul real. Când nu poți fi sigur că o piesă de mobilier este sigură, alege exerciții cu greutatea corpului care nu au nevoie de sprijin.`}];var r=[{label:`Mayo Clinic: siguranța și tehnica antrenamentului cu greutăți`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Biblioteca de exerciții ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:a,sources:r};export{t as default,a as sections,r as sources};